import { useEffect, useId, useRef, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import {
  directionOf,
  firstMeaning,
  normalizeHeadword,
  type LanguageCode,
  type Word,
  LEVELS,
} from '@lexpad/core';
import { Bilingual } from '@/components/ui/Bilingual.js';
import { GrowingText } from '@/components/ui/GrowingText.js';
import { Icon } from '@/components/ui/Icon.js';
import { Sheet } from '@/components/ui/Sheet.js';
import { t } from '@/i18n/index.js';
import { cx } from '@/lib/cx.js';
import { localTimeZone } from '@/lib/format.js';
import { addWord, draftFromWord, saveWordDraft, type WordDraft } from '@/db/mutations.js';
import { VoiceButton } from '@/components/ui/VoiceButton.js';
import { TrialProMark } from '@/features/billing/ProMark.js';
import { NewNotebookSheet } from './NewNotebookSheet.js';
import { NotebookRoute } from './NotebookRoute.js';
import { routeFor, settles } from './route.js';
import type { ApiExample, ApiMeaning, ApiPhrase } from '@/api/types.js';
import { listNotebooks, listWords } from '@/db/repo.js';
import { useLiveQuery } from '@/lib/useLiveQuery.js';
import type { StoredNotebook } from '@/db/schema.js';
import { syncSoon } from '@/sync/store.js';
import { ApiError } from '@/api/errors.js';
import { generateCardWithJob, type GeneratedCard } from '@/features/ai/generate.js';
import { noteAiCard, noteTrouble } from '@/features/review/review.js';
import { cardSnapshot } from '@/features/report/report.js';
import { aiPausedUntil, FEW_CARDS_LEFT, isRefusal } from '@/features/ai/quota.js';
import { leftLine, restLine, useAiAllowance } from '@/features/ai/restLine.js';
import { ProOffer } from '@/features/billing/ProOffer.js';
import { offerable, proHere, useBilling } from '@/features/billing/state.js';
import { Refine } from '@/features/ai/Refine.js';
import { LANGUAGE_NAMES } from '@/features/settings/data.js';
import styles from './AddSheet.module.css';
import { trackWords } from '@/features/celebrate/state.js';
import { SpellingPrompt } from './SpellingPrompt.js';
import { suggestedSpelling } from './spelling.js';

/**
 * How many of the words added since the sheet opened it lists underneath.
 * A layout choice: five rows keep the sheet short above the keyboard.
 */
const RECENT_SHOWN = 5;

interface AddSheetProps {
  notebookId: string;
  targetLang: LanguageCode;
  meaningLang: LanguageCode;
  onClose: () => void;
  /** Called after each successful add, so the caller can react. */
  onAdded?: (wordId: string) => void;
  /**
   * An existing word to edit instead of adding a new one. The same form,
   * filled in, with Save changes instead of Add and no recent list.
   */
  edit?: Word | undefined;
  /** A word to start from, typed by the learner elsewhere (the introduction's word). */
  initialHeadword?: string | undefined;
  /**
   * Opened to say the word rather than type it (the Android widget's and
   * shortcut's microphone): the microphone starts as the sheet opens.
   * `onListenStarted` says it was used, so a reload does not listen again.
   */
  listenOnOpen?: boolean;
  onListenStarted?: () => void;
  /**
   * Opened to type a word at once (the Android widget, shortcut and tile): the word field
   * takes focus once the sheet has opened, which otherwise focuses its own panel.
   * `onFocused` says it was done, so a reload does not do it again.
   */
  typeOnOpen?: boolean;
  onFocused?: () => void;
}

// No level until the AI or the learner sets one (app audit 2026-10-22): a
// pre-selected "B1" claimed something nobody had decided.
const BLANK: WordDraft = { headword: '', meaning: '', category: 'general' };

/**
 * The add sheet: the word and its meaning under visible labels, More
 * details behind a disclosure, and one button at the bottom that is always
 * the next step (app audit 2026-10-22, owner-approved): with a word and no
 * meaning, "Write the card with AI" (and "Save without a meaning" under
 * it); with a meaning, "Add to notebook"; with the AI cards used up, "Add
 * to notebook" with the exact line of when they come back. Underneath, the
 * words added since it opened, each opening its own page — no delete here,
 * because a one-tap delete without undo could lose a learner's word.
 * Enter adds and clears the form for the next word, so a run can be typed
 * without a pointer.
 */
export function AddSheet({
  notebookId,
  targetLang,
  meaningLang,
  onClose,
  onAdded,
  edit,
  initialHeadword,
  listenOnOpen = false,
  onListenStarted,
  typeOnOpen = false,
  onFocused,
}: AddSheetProps): React.JSX.Element {
  const navigate = useNavigate();
  const editing = edit !== undefined;
  const [draft, setDraft] = useState<WordDraft>(() =>
    edit
      ? draftFromWord(edit)
      : initialHeadword === undefined
        ? BLANK
        : { ...BLANK, headword: initialHeadword },
  );
  const [more, setMore] = useState(editing);
  const [error, setError] = useState<string | undefined>(undefined);
  const [justAdded, setJustAdded] = useState<string | undefined>(undefined);
  /**
   * The AI is out for today: Fill was refused, or is resting since an
   * earlier refusal. The word can still be saved, plain, and filled later;
   * an offer of Pro comes only once it is (`restOffer`), never before.
   */
  const [aiOut, setAiOut] = useState(false);
  // The words added since the sheet opened, newest first: what "Added just now" lists.
  const [addedIds, setAddedIds] = useState<string[]>([]);
  const { rest, left } = useAiAllowance();
  const wordId = useId();
  const meaningId = useId();
  const [busy, setBusy] = useState(false);
  const [filling, setFilling] = useState(false);
  // Whether the model has written this card once, which is when a refinement makes sense.
  const [filled, setFilled] = useState(false);
  // What the model wrote, as it wrote it, for Report: the form may have
  // been edited since, and a report is about the model's words.
  const [written, setWritten] = useState<GeneratedCard | undefined>(undefined);
  /** The learner answered "Did you mean …?" for the card in the form. */
  const [spellingAnswered, setSpellingAnswered] = useState(false);
  const [words, setWords] = useState<Word[]>([]);
  const headwordInput = useRef<HTMLInputElement>(null);
  // Which notebook this word is actually going into. It follows what is
  // being typed, because somebody who has two notebooks and types a Persian
  // word means the Persian one whatever the app happens to be showing.
  const [picked, setPicked] = useState<StoredNotebook | undefined>();
  // When the word is in a language no notebook holds, the new-notebook
  // flow opens here rather than sending somebody to Settings and back.
  const [making, setMaking] = useState<{ language: LanguageCode | undefined } | undefined>();
  // What the microphone heard, kept so the sheet can ask for it to be
  // checked. A recogniser is right most of the time and wrong the rest,
  // and the learner is the one person who cannot spot which.
  const [heard, setHeard] = useState('');
  const [voiceProblem, setVoiceProblem] = useState('');
  // Whether the microphone is being offered rather than used. Kept here and
  // not in the button, because the offer belongs under the field where the
  // rest of what the microphone has to say already goes.
  const [offeringVoice, setOfferingVoice] = useState(false);
  // After the sheet's own effect, which moves focus to its panel: a task later.
  const focusedOnOpen = useRef(false);
  useEffect(() => {
    if (!typeOnOpen || editing || focusedOnOpen.current) return;
    focusedOnOpen.current = true;
    const timer = setTimeout(() => {
      headwordInput.current?.focus();
      onFocused?.();
    }, 0);
    return () => {
      clearTimeout(timer);
    };
  }, [typeOnOpen, editing, onFocused]);
  const billing = useBilling((state) => state.state);
  const ensurePlan = useBilling((state) => state.ensure);
  useEffect(() => {
    ensurePlan();
  }, [ensurePlan]);
  const notebooks = useLiveQuery(() => listNotebooks(), undefined, []);

  // Routing is for new words only: an existing word already belongs
  // somewhere, and moving it is what the word's own screen is for.
  const all = notebooks ?? [];
  const here = all.find((notebook) => notebook.id === notebookId);
  const destination = editing ? ({ kind: 'unknown' } as const) : routeFor(draft.headword, all, here);
  const into = picked ?? settles(destination, here) ?? here;
  const writingTo = into?.id ?? notebookId;

  // The recent list and the duplicate check both read the notebook; one read
  // per change keeps them in step.
  const refresh = async (): Promise<void> => {
    setWords(await listWords(writingTo));
  };
  useEffect(() => {
    let live = true;
    void listWords(writingTo).then((list) => {
      if (live) setWords(list);
    });
    return () => {
      live = false;
    };
  }, [writingTo]);

  const set = <K extends keyof WordDraft>(key: K, value: WordDraft[K]): void => {
    setDraft((previous) => ({ ...previous, [key]: value }));
    setError(undefined);
  };

  const senses = draft.extraMeanings ?? [];
  const setSense = (index: number, patch: Partial<ApiMeaning>): void => {
    setDraft((previous) => ({
      ...previous,
      extraMeanings: (previous.extraMeanings ?? []).map((sense, i) =>
        i === index ? { ...sense, ...patch } : sense,
      ),
    }));
  };
  /** The first sense's examples, which the flat fields and moreExamples hold between them. */
  const firstExamples = (): ApiExample[] => {
    const head: ApiExample[] = [];
    if ((draft.example ?? '') !== '' || (draft.translation ?? '') !== '') {
      const first: ApiExample = { sentence: draft.example ?? '' };
      if (draft.translation !== undefined) first.translation = draft.translation;
      head.push(first);
    }
    return [...head, ...(draft.moreExamples ?? [])];
  };
  const updateFirstExamples = (next: ApiExample[]): void => {
    setDraft((previous) => {
      const { example: _example, translation: _translation, moreExamples: _more, ...rest } = previous;
      const [head, ...more] = next;
      const out: WordDraft = { ...rest };
      if (head !== undefined) {
        out.example = head.sentence;
        if (head.translation !== undefined) out.translation = head.translation;
      }
      if (more.length > 0) out.moreExamples = more;
      return out;
    });
  };
  /** The example rows of one sense: each removable, plus a way to add one. */
  const renderExamples = (
    examples: ApiExample[],
    update: (next: ApiExample[]) => void,
    senseNo: number,
  ): React.JSX.Element => {
    const rows = examples.length === 0 ? [{ sentence: '' }] : examples;
    const label = (key: 'add.example' | 'add.translation', k: number): string =>
      senseNo === 1 && k === 0 ? t(key) : `${t('add.senseN', { n: senseNo })}: ${t(key)} ${k + 1}`;
    const change = (k: number, patch: Partial<ApiExample>): void => {
      update(rows.map((row, i) => (i === k ? { ...row, ...patch } : row)));
    };
    return (
      <>
        {rows.map((row, k) => (
          <div key={k} className={styles.exampleRow}>
            {examples.length > 0 && (
              <div className={styles.senseHead}>
                <span className={styles.senseLabel}>{t('add.exampleN', { n: k + 1 })}</span>
                <button
                  type="button"
                  className={styles.recentRemove}
                  aria-label={
                    senseNo === 1
                      ? t('add.removeExample', { n: k + 1 })
                      : `${t('add.senseN', { n: senseNo })}: ${t('add.removeExample', { n: k + 1 })}`
                  }
                  onClick={() => {
                    update(examples.filter((_, i) => i !== k));
                  }}
                >
                  <Icon name="close" size={16} weight={2} />
                </button>
              </div>
            )}
            <GrowingText
              className={cx(styles.field, styles.grow)}
              value={row.sentence}
              dir={directionOf(intoTarget)}
              placeholder={t('add.example')}
              aria-label={label('add.example', k)}
              onChange={(sentence) => {
                change(k, { sentence });
              }}
            />
            <input
              className={styles.field}
              value={row.translation ?? ''}
              dir={directionOf(intoMeaning)}
              placeholder={t('add.translation')}
              aria-label={label('add.translation', k)}
              onChange={(event) => {
                change(k, { translation: event.target.value });
              }}
            />
          </div>
        ))}
        {examples.length > 0 && examples.length < 5 && (
          <button
            type="button"
            className={styles.more}
            onClick={() => {
              update([...examples, { sentence: '' }]);
            }}
          >
            <Icon name="plus" size={14} weight={2} />
            {t('add.addExample')}
          </button>
        )}
      </>
    );
  };
  const addSense = (): void => {
    setDraft((previous) => ({
      ...previous,
      extraMeanings: [...(previous.extraMeanings ?? []), { meaning: '', examples: [] }],
    }));
    setMore(true);
  };
  const removeSense = (index: number): void => {
    setDraft((previous) => ({
      ...previous,
      extraMeanings: (previous.extraMeanings ?? []).filter((_, i) => i !== index),
    }));
  };
  /** Drops the first sense; the next one moves into the flat fields. */
  const removeFirstSense = (): void => {
    setDraft((previous) => {
      const [next, ...rest] = previous.extraMeanings ?? [];
      if (next === undefined) return previous;
      const [example, ...moreExamples] = next.examples ?? [];
      const {
        gloss: _gloss,
        example: _example,
        translation: _translation,
        moreExamples: _more,
        ...keep
      } = previous;
      const promoted: WordDraft = { ...keep, meaning: next.meaning, extraMeanings: rest };
      if (next.gloss !== undefined) promoted.gloss = next.gloss;
      if (example !== undefined) promoted.example = example.sentence;
      if (example?.translation !== undefined) promoted.translation = example.translation;
      if (moreExamples.length > 0) promoted.moreExamples = moreExamples;
      return promoted;
    });
  };
  const [newCollocation, setNewCollocation] = useState('');
  const addCollocation = (): void => {
    const text = newCollocation.trim();
    if (text === '') return;
    setDraft((previous) => ({ ...previous, collocations: [...(previous.collocations ?? []), text] }));
    setNewCollocation('');
  };
  const removeCollocation = (index: number): void => {
    setDraft((previous) => ({
      ...previous,
      collocations: (previous.collocations ?? []).filter((_, i) => i !== index),
    }));
  };
  type PhraseList = 'expressions' | 'relatedWords';
  const setPhrase = (list: PhraseList, index: number, patch: Partial<ApiPhrase>): void => {
    setDraft((previous) => ({
      ...previous,
      [list]: (previous[list] ?? []).map((phrase, i) => (i === index ? { ...phrase, ...patch } : phrase)),
    }));
  };
  const addPhrase = (list: PhraseList): void => {
    setDraft((previous) => ({ ...previous, [list]: [...(previous[list] ?? []), { text: '' }] }));
  };
  const removePhrase = (list: PhraseList, index: number): void => {
    setDraft((previous) => ({ ...previous, [list]: (previous[list] ?? []).filter((_, i) => i !== index) }));
  };
  // What the model wrote beyond the flat fields, so the learner knows the
  // card is richer than the form shows even with the details closed.
  const extras = {
    meanings: senses.filter((sense) => sense.meaning.trim() !== '').length + 1,
    collocations: (draft.collocations ?? []).length,
    related: (draft.relatedWords ?? []).length,
  };
  const hasExtras = extras.meanings > 1 || extras.collocations > 0 || extras.related > 0;

  // A word in a script no notebook holds has nowhere to go until one is
  // made: nothing saves it, and the AI writes nothing for it, meanwhile.
  const nowhere = destination.kind === 'missing' && picked === undefined;
  const canSave = draft.headword.trim() !== '' && draft.meaning.trim() !== '' && !filling && !nowhere;
  // The fields follow the notebook the word is going into, not the one the
  // sheet was opened from: typing a Persian word into an English notebook
  // switches the destination, and a placeholder still saying "English word"
  // would be describing somewhere the word is not going.
  const intoTarget = into?.targetLang ?? targetLang;
  const intoMeaning = into?.meaningLang ?? meaningLang;
  const targetName = LANGUAGE_NAMES[intoTarget];
  const meaningName = LANGUAGE_NAMES[intoMeaning];
  // Saying a word is part of Pro, with the exemption every paid feature
  // here honours: a notebook Lexpad never charges for is not locked out of
  // it. The languages are the destination's, so the answer follows the word
  // being typed the same way the microphone's own language does.
  const voiceLocked = !proHere(billing, intoTarget, intoMeaning);
  // Whether tapping it will produce an offer or nothing at all, from the
  // same rule the offer itself uses rather than a second copy of it.
  const canOfferVoice = offerable(billing, intoTarget, intoMeaning);
  const categories = [...new Set(['general', ...words.map((word) => word.category)])].sort();
  const justNow = addedIds
    .map((id) => words.find((word) => word.id === id))
    .filter((word): word is Word => word !== undefined)
    .slice(0, RECENT_SHOWN);
  const typedWord = draft.headword.trim() !== '';
  const meaningEmpty = draft.meaning.trim() === '';
  // Resting: refused just now, or since an earlier refusal that has not run out.
  const resting = aiOut || rest !== undefined;
  // The next step is the AI's: a word, no meaning, and AI cards to spend.
  const offerAi = !editing && typedWord && meaningEmpty && !resting && !nowhere;
  // A word with no meaning may be kept as it is; it is filled later.
  const canSavePlain = !editing && typedWord && !filling && !nowhere;
  const fewLeft =
    !editing && !resting && left !== undefined && left.left > 0 && left.left <= FEW_CARDS_LEFT
      ? left
      : undefined;

  /**
   * Saves the form. `andClose` is the button's way; Enter and Add another
   * keep the sheet open and cleared, so a run of words can be typed. A word
   * the notebook already has moves to the top instead of being refused, and
   * the message says so.
   */
  const submit = async (andClose: boolean, plain = false): Promise<void> => {
    // Plain: the AI could not fill it, so the word is kept with what the
    // learner typed and no meaning, to be filled later.
    const savable = canSave || (plain && canSavePlain);
    if (!savable) return;
    setBusy(true);
    try {
      if (edit) {
        await saveWordDraft(edit.id, draft);
        void syncSoon();
        onClose();
        return;
      }
      const headword = draft.headword.trim();
      const norm = normalizeHeadword(headword);
      const known = words.some((word) => normalizeHeadword(word.headword) === norm);
      const id = await trackWords(() => addWord(writingTo, draft, localTimeZone()));
      // A card the AI wrote, kept: one more in a run the phone apps may hand
      // to the store's rating dialog after the sheet closes (`features/review`).
      if (filled && !plain) noteAiCard('saved');
      void syncSoon();
      onAdded?.(id);
      if (andClose) {
        onClose();
        return;
      }
      setJustAdded(known ? t('add.raised', { word: headword }) : t('add.justAdded', { word: headword }));
      setAddedIds((previous) => [id, ...previous.filter((one) => one !== id)]);
      setDraft(BLANK);
      setFilled(false);
      setWritten(undefined);
      setSpellingAnswered(false);
      await refresh();
      headwordInput.current?.focus();
    } finally {
      setBusy(false);
    }
  };

  /**
   * Asks the model for the card and pours what comes back into the form. A
   * hint is the learner's reaction to the first attempt: "simpler", "more
   * examples", or their own words.
   */
  const fill = async (hint?: string): Promise<void> => {
    const headword = draft.headword.trim();
    if (headword === '' || filling) return;
    setError(undefined);
    // Resting since an earlier refusal: say so at once rather than ask a
    // server that has already said no today.
    if ((await aiPausedUntil()) !== undefined) {
      setAiOut(true);
      return;
    }
    setFilling(true);
    // Asking again with a hint means the first card was not right.
    if (hint !== undefined) noteAiCard('retried');
    try {
      const generated = await generateCardWithJob(writingTo, headword, hint === undefined ? {} : { hint });
      const { card } = generated;
      setWritten(generated);
      setFilled(true);
      setSpellingAnswered(false);
      // The model wrote a whole card: senses, examples, collocations. Open
      // the details so the learner sees what arrived instead of a pill that
      // only counts it.
      setMore(true);
      setDraft((previous) => ({
        ...previous,
        ...card,
        headword: previous.headword,
        // A topic the model chose is worth keeping; "general" is not.
        ...(card.category === undefined || card.category === 'general'
          ? { category: previous.category ?? 'general' }
          : { category: card.category }),
      }));
    } catch (cause) {
      noteAiCard('failed');
      if (isRefusal(cause)) {
        setAiOut(true);
        return;
      }
      // An error the learner hit: no rating request today.
      noteTrouble();
      // The server explains a refusal it wants the user to act on, such as an
      // unconfirmed address; anything else gets the generic line.
      setError(
        cause instanceof ApiError && cause.code === 'email_unverified' ? cause.message : t('add.fillFailed'),
      );
    } finally {
      setFilling(false);
    }
  };

  // Asked only about a card the model just wrote, and only until answered.
  // The card is already for the suggested word, so Use renames and nothing
  // goes back to the model; Keep mine leaves the suggestion on the word for
  // its own page to ask once more.
  const suggestion =
    !editing && filled && !filling && !spellingAnswered
      ? suggestedSpelling(draft.headword, draft.correction)
      : undefined;
  const takeSuggestion = (word: string): void => {
    setDraft((previous) => {
      const { correction: _correction, ...rest } = previous;
      return { ...rest, headword: word };
    });
    setSpellingAnswered(true);
  };

  const onKeyDown = (event: React.KeyboardEvent): void => {
    if (event.key === 'Enter' && !event.shiftKey && event.target instanceof HTMLInputElement) {
      event.preventDefault();
      void submit(false);
    }
  };

  if (making !== undefined) {
    return (
      <NewNotebookSheet
        {...(making.language === undefined ? {} : { startAt: making.language })}
        onCreated={(made) => {
          // Straight back to the word they were writing, now with somewhere
          // for it to go.
          setMaking(undefined);
          const fresh = all.find((notebook) => notebook.id === made);
          if (fresh !== undefined) setPicked(fresh);
        }}
        onClose={() => {
          setMaking(undefined);
        }}
      />
    );
  }

  return (
    <Sheet title={editing ? t('edit.title') : t('add.title')} onClose={onClose}>
      {justAdded !== undefined && <div className={styles.justAdded}>{justAdded}</div>}

      {!editing && (
        <label className={styles.fieldLabel} htmlFor={wordId}>
          {t('add.word')}
        </label>
      )}
      <div className={styles.headwordRow}>
        <input
          ref={headwordInput}
          id={wordId}
          className={styles.input}
          value={draft.headword}
          dir={directionOf(intoTarget)}
          placeholder={t('add.wordPlaceholder', { language: targetName })}
          {...(editing ? { 'aria-label': t('add.word') } : {})}
          autoCapitalize="off"
          autoComplete="off"
          spellCheck={false}
          autoFocus={!editing}
          onChange={(event) => {
            set('headword', event.target.value);
          }}
          onKeyDown={onKeyDown}
        />
        {/* Listening in the destination's language, which is what turns a
            guess into a good guess. It never saves: what it hears lands
            here to be read and corrected. */}
        {/* Voice input is Pro: during the trial it wears the gold mark. */}
        <span className={styles.voiceWrap}>
          <VoiceButton
            lang={intoTarget}
            locked={voiceLocked}
            lockMark={false}
            lockedLabel={t('voice.sayPro')}
            autoStart={listenOnOpen && !editing}
            onAutoStarted={onListenStarted}
            onLocked={() => {
              setHeard('');
              setVoiceProblem('');
              setOfferingVoice(true);
            }}
            onHeard={(text) => {
              set('headword', text);
              setHeard(text);
              setVoiceProblem('');
              setOfferingVoice(false);
              headwordInput.current?.focus();
            }}
            onProblem={(message) => {
              setVoiceProblem(message);
              setHeard('');
            }}
          />
          {/* The gold mark says "this is Pro, yours for now" during the trial
              only; a free account's microphone wears nothing, and its tap
              explains itself. */}
          <span className={styles.voiceMark}>
            <TrialProMark />
          </span>
        </span>
      </div>
      {/* One slot under the field for whatever the microphone has to say,
          so nothing jumps as it changes. It sits here rather than inside
          the row above, where a paragraph would squeeze the field. */}
      {offeringVoice ? (
        // The offer goes where the microphone's own messages go, so the
        // field never moves for one and stays put for the other.
        canOfferVoice ? (
          <ProOffer occasion="voice" subtle about={{ targetLang: intoTarget, meaningLang: intoMeaning }} />
        ) : (
          // Nothing to sell here -- selling switched off, or a price we are
          // not sure of. The button still answers, because a control that
          // does nothing at all reads as broken.
          <p className={styles.heard} role="status">
            {t('voice.proLine')}
          </p>
        )
      ) : (
        (heard !== '' || voiceProblem !== '') && (
          <p className={cx(styles.heard, voiceProblem !== '' && styles.heardBad)} role="status">
            {voiceProblem !== '' ? voiceProblem : t('voice.heard', { text: heard })}
          </p>
        )
      )}

      {suggestion !== undefined && (
        <SpellingPrompt
          suggestion={suggestion}
          lang={intoTarget}
          onUse={() => {
            takeSuggestion(suggestion);
          }}
          onKeep={() => {
            setSpellingAnswered(true);
          }}
        />
      )}

      <NotebookRoute
        destination={destination}
        chosen={into}
        onChoose={setPicked}
        onMake={(language) => {
          setMaking({ language });
        }}
      />

      {filling ? (
        <>
          <div className={styles.filling} role="status">
            {t('add.filling')}
          </div>
          {/* While the model writes, the shape of what is coming shows, so
              the wait reads as a card taking form rather than a spinner.
              Above the toolbar on purpose: the sheet grows from the bottom,
              so what is added here moves the word up and leaves the button
              that was just pressed where the finger is. When the details
              are already open their own fields are the shape. */}
          {!more && <CardSkeleton />}
        </>
      ) : editing ? null : (
        <>
          <label className={styles.fieldLabel} htmlFor={meaningId}>
            {t('add.meaningLabel', { language: meaningName })}
            <span className={styles.fieldOptional}> · {t('add.meaningOptional')}</span>
          </label>
          <input
            id={meaningId}
            className={cx(styles.input, styles.inputMeaning)}
            value={draft.meaning}
            dir={directionOf(intoMeaning)}
            placeholder={
              resting ? t('add.meaningPlaceholder', { language: meaningName }) : t('add.meaningPlaceholderAi')
            }
            onChange={(event) => {
              set('meaning', event.target.value);
            }}
            onKeyDown={onKeyDown}
          />
        </>
      )}
      {fewLeft !== undefined && <p className={styles.fewLeft}>{leftLine(fewLeft)}</p>}

      <div className={styles.toolbar}>
        <button
          type="button"
          className={cx(styles.more, more && styles.moreOpen)}
          aria-expanded={more}
          onClick={() => {
            setMore(!more);
          }}
        >
          {more ? t('add.fewerDetails') : t('add.moreDetails')}
          <Icon name="chevronDown" size={14} weight={2} />
        </button>
      </div>

      {/* AI cards used up: the word is never the casualty. The line says
          exactly when they come back (the server's numbers), the main
          button keeps the word as it is, and — only where Pro can honestly
          be offered — one line says what Pro gives. */}
      {resting && !filling && (
        <div className={styles.aiOut} role="status">
          <p className={styles.aiOutText}>
            {rest?.kind === undefined ? (editing ? t('ai.resting') : t('add.aiOut')) : restLine(rest)}
          </p>
          {!editing && (
            <ProOffer occasion="resting" line about={{ targetLang: intoTarget, meaningLang: intoMeaning }} />
          )}
        </div>
      )}

      {filled && !filling && !editing && (
        <Refine
          onRefine={(hint) => {
            void fill(hint);
          }}
          report={
            written === undefined
              ? undefined
              : () => ({
                  surface: 'card',
                  snapshot: cardSnapshot(written.card),
                  headword: written.card.headword || draft.headword,
                  targetLang: intoTarget,
                  meaningLang: intoMeaning,
                  aiJobId: written.jobId,
                })
          }
        />
      )}

      {hasExtras && !more && (
        <button
          type="button"
          className={styles.extras}
          onClick={() => {
            setMore(true);
          }}
        >
          <Icon name="sparkles" size={13} weight={2} />
          <span>{t('add.extras', extras)}</span>
          <span className={styles.extrasHint}>{t('add.extrasHint')}</span>
        </button>
      )}

      {more && (
        <div className={styles.details}>
          <section className={styles.sense}>
            <div className={styles.senseHead}>
              <span className={styles.senseBadge}>1</span>
              <span className={styles.senseTitle}>{t('add.senseN', { n: 1 })}</span>
              {senses.length > 0 && (
                <button
                  type="button"
                  className={styles.recentRemove}
                  aria-label={t('add.removeSense', { n: 1 })}
                  onClick={removeFirstSense}
                >
                  <Icon name="close" size={16} weight={2} />
                </button>
              )}
            </div>
            {editing && (
              <input
                className={styles.field}
                value={draft.meaning}
                dir={directionOf(intoMeaning)}
                placeholder={t('add.meaningPlaceholder', { language: meaningName })}
                aria-label={t('add.meaning')}
                onChange={(event) => {
                  set('meaning', event.target.value);
                }}
              />
            )}
            <input
              className={styles.field}
              value={draft.gloss ?? ''}
              placeholder={t('add.gloss')}
              aria-label={t('add.gloss')}
              onChange={(event) => {
                set('gloss', event.target.value);
              }}
            />
            <div className={styles.subLabel}>{t('add.examples')}</div>
            <div className={styles.examples}>{renderExamples(firstExamples(), updateFirstExamples, 1)}</div>
          </section>
          {senses.map((sense, index) => {
            const n = index + 2;
            return (
              <section key={index} className={styles.sense}>
                <div className={styles.senseHead}>
                  <span className={styles.senseBadge}>{n}</span>
                  <span className={styles.senseTitle}>{t('add.senseN', { n })}</span>
                  <button
                    type="button"
                    className={styles.recentRemove}
                    aria-label={t('add.removeSense', { n })}
                    onClick={() => {
                      removeSense(index);
                    }}
                  >
                    <Icon name="close" size={16} weight={2} />
                  </button>
                </div>
                <input
                  className={styles.field}
                  value={sense.meaning}
                  dir={directionOf(intoMeaning)}
                  placeholder={t('add.meaningPlaceholder', { language: meaningName })}
                  aria-label={t('add.senseMeaning', { n })}
                  onChange={(event) => {
                    setSense(index, { meaning: event.target.value });
                  }}
                />
                <input
                  className={styles.field}
                  value={sense.gloss ?? ''}
                  placeholder={t('add.gloss')}
                  aria-label={t('add.senseGloss', { n })}
                  onChange={(event) => {
                    setSense(index, { gloss: event.target.value });
                  }}
                />
                <div className={styles.subLabel}>{t('add.examples')}</div>
                <div className={styles.examples}>
                  {renderExamples(
                    sense.examples ?? [],
                    (next) => {
                      setSense(index, { examples: next });
                    },
                    n,
                  )}
                </div>
              </section>
            );
          })}
          <button type="button" className={styles.more} onClick={addSense}>
            <Icon name="plus" size={14} weight={2} />
            {t('add.anotherMeaning')}
          </button>
          <div className={styles.sectionTitle}>{t('add.detailsTitle')}</div>
          <div className={styles.pair}>
            <label className={styles.selectLabel}>
              <span>{t('add.category')}</span>
              <select
                className={styles.select}
                value={draft.category ?? 'general'}
                onChange={(event) => {
                  set('category', event.target.value);
                }}
              >
                {categories.map((category) => (
                  <option key={category} value={category}>
                    {category.replace(/-/g, ' ')}
                  </option>
                ))}
              </select>
            </label>
            <label className={styles.selectLabel}>
              <span>{t('add.level')}</span>
              <select
                className={styles.select}
                value={draft.level ?? ''}
                onChange={(event) => {
                  setDraft((previous) => {
                    const { level: _level, ...rest } = previous;
                    return event.target.value === '' ? rest : { ...rest, level: event.target.value };
                  });
                }}
              >
                <option value="">{t('add.levelNotSet')}</option>
                {LEVELS.map((level) => (
                  <option key={level} value={level}>
                    {level}
                  </option>
                ))}
              </select>
            </label>
          </div>
          <div className={styles.pair}>
            <input
              className={cx(styles.field, styles.small, styles.mono)}
              value={draft.pronunciation ?? ''}
              placeholder={t('add.pronunciation')}
              aria-label={t('add.pronunciation')}
              spellCheck={false}
              onChange={(event) => {
                set('pronunciation', event.target.value);
              }}
            />
            <input
              className={cx(styles.field, styles.small)}
              value={draft.pos ?? ''}
              placeholder={t('add.pos')}
              aria-label={t('add.pos')}
              spellCheck={false}
              onChange={(event) => {
                set('pos', event.target.value);
              }}
            />
          </div>
          <button
            type="button"
            className={styles.tricky}
            role="switch"
            aria-checked={draft.trickySpelling === true}
            onClick={() => {
              set('trickySpelling', draft.trickySpelling !== true);
            }}
          >
            <span>{t('add.tricky')}</span>
            <span className={cx(styles.switch, draft.trickySpelling === true && styles.switchOn)}>
              <span className={styles.knob} />
            </span>
          </button>
          <div className={styles.sectionTitle}>{t('add.collocations')}</div>
          {(draft.collocations ?? []).length > 0 && (
            <div className={styles.chips}>
              {(draft.collocations ?? []).map((item, index) => (
                <span key={`${item}-${index}`} className={styles.chip}>
                  <Bilingual lang={intoTarget}>{item}</Bilingual>
                  <button
                    type="button"
                    className={styles.chipRemove}
                    aria-label={t('add.removeItem', { item })}
                    onClick={() => {
                      removeCollocation(index);
                    }}
                  >
                    <Icon name="close" size={12} weight={2.2} />
                  </button>
                </span>
              ))}
            </div>
          )}
          <input
            className={styles.field}
            value={newCollocation}
            dir={directionOf(intoTarget)}
            placeholder={t('add.addCollocation')}
            aria-label={t('add.addCollocation')}
            onChange={(event) => {
              setNewCollocation(event.target.value);
            }}
            onKeyDown={(event) => {
              if (event.key === 'Enter') {
                event.preventDefault();
                addCollocation();
              }
            }}
          />

          {(['expressions', 'relatedWords'] as const).map((list) => (
            <div key={list} className={styles.phraseList}>
              <div className={styles.sectionTitle}>
                {list === 'expressions' ? t('add.expressions') : t('add.related')}
              </div>
              {(draft[list] ?? []).map((phrase, index) => (
                <div key={index} className={styles.phraseRow}>
                  <input
                    className={cx(styles.field, styles.small)}
                    value={phrase.text}
                    dir={directionOf(intoTarget)}
                    placeholder={t('add.phraseText')}
                    aria-label={`${list === 'expressions' ? t('add.expressions') : t('add.related')} ${index + 1}: ${t('add.phraseText')}`}
                    onChange={(event) => {
                      setPhrase(list, index, { text: event.target.value });
                    }}
                  />
                  <input
                    className={cx(styles.field, styles.small)}
                    value={phrase.translation ?? ''}
                    dir={directionOf(intoMeaning)}
                    placeholder={t('add.phraseTranslation')}
                    aria-label={`${list === 'expressions' ? t('add.expressions') : t('add.related')} ${index + 1}: ${t('add.phraseTranslation')}`}
                    onChange={(event) => {
                      setPhrase(list, index, { translation: event.target.value });
                    }}
                  />
                  <button
                    type="button"
                    className={styles.recentRemove}
                    aria-label={t('add.removeItem', { item: phrase.text || String(index + 1) })}
                    onClick={() => {
                      removePhrase(list, index);
                    }}
                  >
                    <Icon name="close" size={16} weight={2} />
                  </button>
                </div>
              ))}
              <button
                type="button"
                className={styles.more}
                onClick={() => {
                  addPhrase(list);
                }}
              >
                <Icon name="plus" size={14} weight={2} />
                {list === 'expressions' ? t('add.addExpression') : t('add.addRelated')}
              </button>
            </div>
          ))}
          <div className={styles.sectionTitle}>{t('add.notesTitle')}</div>
          <textarea
            className={styles.memo}
            value={draft.usageNote ?? ''}
            rows={2}
            dir={directionOf(intoMeaning)}
            placeholder={t('add.usageNote')}
            aria-label={t('add.usageNote')}
            onChange={(event) => {
              set('usageNote', event.target.value);
            }}
          />
          {(editing || draft.correction !== undefined) && (
            <input
              className={styles.field}
              value={draft.correction ?? ''}
              dir={directionOf(intoTarget)}
              placeholder={t('add.correction')}
              aria-label={t('add.correction')}
              onChange={(event) => {
                set('correction', event.target.value);
              }}
            />
          )}
          {!editing && (
            <textarea
              className={styles.memo}
              value={draft.memo ?? ''}
              rows={2}
              dir="auto"
              placeholder={t('add.memo')}
              aria-label={t('add.memo')}
              onChange={(event) => {
                set('memo', event.target.value);
              }}
            />
          )}
        </div>
      )}

      {error !== undefined && (
        <p className={styles.error} role="alert">
          {error}
        </p>
      )}

      {!editing && justNow.length > 0 && (
        <div className={styles.recent}>
          <div className={styles.recentHead}>
            <span className={styles.recentLabel}>{t('add.justNow')}</span>
            {justNow.length >= 2 && (
              <button
                type="button"
                className={styles.recentAction}
                onClick={() => {
                  onClose();
                  void navigate(`/session?deck=group&ids=${justNow.map((word) => word.id).join(',')}`);
                }}
              >
                {t('add.practiseThese', { count: justNow.length })}
              </button>
            )}
          </div>
          {justNow.map((word) => (
            <button
              key={word.id}
              type="button"
              className={styles.recentOpen}
              aria-label={t('add.openWord', { word: word.headword })}
              onClick={() => {
                onClose();
                void navigate(`/words/${word.id}`);
              }}
            >
              <span className={styles.recentWord}>
                <Bilingual lang={intoTarget}>{word.headword}</Bilingual>
              </span>
              <span className={styles.recentMeaning}>
                <Bilingual lang={intoMeaning}>{firstMeaning(word)}</Bilingual>
              </span>
            </button>
          ))}
        </div>
      )}

      {/* Last in the sheet, so it can reach down over the sheet's own bottom
          padding while it sticks. */}
      <div className={cx(styles.saveRow, offerAi && !filling && styles.saveStack)}>
        {editing ? (
          <button
            type="button"
            className={cx(styles.save, canSave && styles.saveReady)}
            disabled={!canSave || busy}
            onClick={() => {
              void submit(true);
            }}
          >
            {canSave ? t('edit.save') : t('add.saveDisabled')}
          </button>
        ) : filling ? (
          <button type="button" className={cx(styles.save, styles.saveReady)} disabled aria-busy="true">
            <span className={styles.saveInner}>
              <span className={styles.spinner} aria-hidden="true" />
              {t('add.fillWorking')}
            </span>
          </button>
        ) : offerAi ? (
          <>
            <button
              type="button"
              className={cx(styles.save, styles.saveReady)}
              disabled={busy}
              onClick={() => {
                void fill();
              }}
            >
              <span className={styles.saveInner}>
                <Icon name="sparkles" size={18} weight={2} />
                {t('add.writeWithAi')}
              </span>
            </button>
            <button
              type="button"
              className={styles.textAction}
              disabled={busy}
              onClick={() => {
                void submit(true, true);
              }}
            >
              {t('add.savePlain')}
            </button>
          </>
        ) : (
          <>
            <button
              type="button"
              className={cx(styles.save, (canSave || canSavePlain) && styles.saveReady)}
              disabled={!(canSave || canSavePlain) || busy}
              onClick={() => {
                void submit(true, !canSave);
              }}
            >
              {t('add.save')}
            </button>
            {(canSave || canSavePlain) && (
              <button
                type="button"
                className={cx(styles.save, styles.saveAnother)}
                disabled={busy}
                onClick={() => {
                  void submit(false, !canSave);
                }}
              >
                {t('add.addAnother')}
              </button>
            )}
          </>
        )}
      </div>
    </Sheet>
  );
}

/**
 * The outline of a card being written: one sense with a definition and two
 * examples, the way the details show it once it arrives. Decoration only;
 * the status line above the toolbar is what a screen reader hears.
 */
function CardSkeleton(): React.JSX.Element {
  return (
    <div className={styles.skeleton} aria-hidden="true" data-testid="card-skeleton">
      <div className={styles.skeletonHead}>
        <span className={styles.senseBadge}>1</span>
        <span className={cx(styles.skeletonBar, styles.skeletonTitle)} />
      </div>
      <span className={cx(styles.skeletonBar, styles.skeletonWide)} />
      <span className={cx(styles.skeletonBar, styles.skeletonShort)} />
      <span className={cx(styles.skeletonBar, styles.skeletonMid)} />
      <span className={cx(styles.skeletonBar, styles.skeletonWide)} />
    </div>
  );
}
