import { useLayoutEffect, useRef } from 'react';

/**
 * A one-line text field that grows with what is typed, up to the height its
 * class allows (then it scrolls), for a sentence that would be cut off in an
 * `<input>` ("every le…"). Enter does not start a new line: a sentence is
 * one line of text, however it wraps.
 */
export function GrowingText({
  value,
  onChange,
  className,
  ...rest
}: Omit<React.TextareaHTMLAttributes<HTMLTextAreaElement>, 'onChange' | 'value' | 'rows'> & {
  value: string;
  onChange: (value: string) => void;
}): React.JSX.Element {
  const box = useRef<HTMLTextAreaElement>(null);
  useLayoutEffect(() => {
    const element = box.current;
    if (element === null) return;
    element.style.height = 'auto';
    // The border is outside scrollHeight; without it the box scrolls by two pixels.
    const border = element.offsetHeight - element.clientHeight;
    element.style.height = `${String(element.scrollHeight + border)}px`;
  }, [value]);
  return (
    <textarea
      ref={box}
      rows={1}
      className={className}
      value={value}
      onChange={(event) => {
        onChange(event.target.value.replace(/\n/g, ' '));
      }}
      onKeyDown={(event) => {
        if (event.key === 'Enter') event.preventDefault();
      }}
      {...rest}
    />
  );
}
